cd /workspace && python3 - <<'EOF'
import json, math
def hook(pairs):
    d = dict(pairs)
    if len(d) != len(pairs): raise ValueError('dup')
    return d
def pf(s):
    v = float(s)
    if not math.isfinite(v): raise ValueError('inf')
    return v
for tok in ['1'*4301, '-'+'1'*4301, '1'*4300, '-'+'1'*4300]:
    try:
        v = json.loads(tok, object_pairs_hook=hook, parse_float=pf)
        print('ok len=%d sign=%s' % (len(tok), tok[0]=='-'))
    except Exception as e:
        print('ERR len=%d sign=%s: %s' % (len(tok), tok[0]=='-', str(e)[:60]))
# floats
for tok in ['1e400', '1E+400', '-1e400', '1e-4000', '1e99999999999999999999', '0.0000001e-400']:
    try:
        v = json.loads(tok, object_pairs_hook=hook, parse_float=pf)
        print('float %r -> %r' % (tok, v))
    except Exception as e:
        print('float %r ERR %s' % (tok, str(e)[:60]))
EOF
